// Characterization tests: pin CURRENT client-visible behaviour of the orders HTTP API.
// The downstream pricing service is replaced by a hand-written in-process fake.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 60 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, {
    method,
    headers: body !== undefined || raw !== undefined ? { 'content-type': 'application/json' } : {},
    body: raw ?? (body === undefined ? undefined : JSON.stringify(body)),
  })
  return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
}
const post = (items) => call('POST', '/orders', { items })

// Tests run in order within this file; ids come from a process-wide counter.
test('POST /orders creates an order: 201, json, sequential string id', async () => {
  const r = await post([{ sku: 'A', qty: 2 }])
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, { id: '1', items: [{ sku: 'A', qty: 2 }], total: 20 })
  const r2 = await post([{ sku: 'A', qty: 1 }])
  assert.equal(r2.body.id, '2')
})

test('POST total sums price*qty across items', async () => {
  const r = await post([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }])
  assert.equal(r.body.total, 61)
})

test('POST total is floored to whole euros', async () => {
  // 25.5 * 1 = 25.5
  assert.equal((await post([{ sku: 'B', qty: 1 }])).body.total, 25)
})

test('POST no discount at exactly 100', async () => {
  // 10*10 = 100
  assert.equal((await post([{ sku: 'A', qty: 10 }])).body.total, 100)
})

test('POST 10% discount when raw total is above 100, then floored', async () => {
  // 101 -> 90.9 -> 90 ; 60*2+10 = 130 -> 117
  assert.equal((await post([{ sku: 'A', qty: 1 }, { sku: 'C', qty: 1 }, { sku: 'B', qty: 1 }])).body.total, 83) // 95.5 no discount -> 95? see below
})

test('POST discount boundary values', async () => {
  assert.equal((await post([{ sku: 'C', qty: 2 }, { sku: 'A', qty: 1 }])).body.total, 117)
  assert.equal((await post([{ sku: 'C', qty: 1 }, { sku: 'B', qty: 1 }, { sku: 'A', qty: 2 }])).body.total, 95)
})

test('POST 400 {error} for missing, empty, non-array items and invalid JSON', async () => {
  for (const r of [
    await call('POST', '/orders', {}),
    await call('POST', '/orders', { items: [] }),
    await call('POST', '/orders', { items: 'A' }),
    await call('POST', '/orders', undefined, '{not json'),
    await call('POST', '/orders', undefined, 'null'),
  ]) {
    assert.equal(r.status, 400)
    assert.deepEqual(r.body, { error: 'items required' })
  }
})

test('POST unknown sku (price undefined) yields 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null, no validation.
  const r = await post([{ sku: 'ZZZ', qty: 1 }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST item without qty yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — undefined qty gives NaN.
  const r = await post([{ sku: 'A' }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('GET /orders/{id} returns the stored order', async () => {
  const created = (await post([{ sku: 'B', qty: 2 }])).body
  const r = await call('GET', `/orders/${created.id}`)
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('GET /orders/{id} unknown id returns 200 {error: not found}', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is reported with status 200, not 404.
  const r = await call('GET', '/orders/does-not-exist')
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('unrouted paths and methods return 404 {error: no route}', async () => {
  for (const [m, p] of [['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/x'], ['GET', '/orders/'], ['GET', '/']]) {
    const r = await call(m, p)
    assert.equal(r.status, 404, `${m} ${p}`)
    assert.deepEqual(r.body, { error: 'no route' })
  }
})
EOF
